@import "tailwindcss";

@theme {
  --color-bg-primary: #0A0A0A;
  --color-bg-secondary: #111111;
  --color-bg-elevated: #1A1A1A;
  --color-text-primary: #FFFFFF;
  --color-text-secondary: #A0A0A0;
  --color-text-muted: #808080;
  --color-accent: #3B82F6;
  --color-accent-hover: #2563EB;
  --color-border: #2A2A2A;
}

html {
  height: 100%;
  scroll-behavior: smooth;
}

html,
body {
  max-width: 100vw;
  overflow-x: hidden;
}

body {
  min-height: 100%;
  color: var(--color-text-primary);
  background: var(--color-bg-primary);
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

* {
  box-sizing: border-box;
  padding: 0;
  margin: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}

img {
  max-width: 100%;
  display: block;
}

/* Custom scrollbar */
::-webkit-scrollbar {
  width: 8px;
  height: 8px;
}

::-webkit-scrollbar-track {
  background: var(--color-bg-primary);
}

::-webkit-scrollbar-thumb {
  background: #333;
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: #444;
}

/* Selection */
::selection {
  background: rgba(59, 130, 246, 0.3);
  color: #fff;
}

import type { Metadata } from "next";
import { Inter } from "next/font/google";
import "./globals.css";
import "remixicon/fonts/remixicon.css";

const inter = Inter({
  variable: "--font-inter",
  subsets: ["latin"],
  display: "swap",
});

export const metadata: Metadata = {
  title: "Leap Studio — Your Reinvention and Experience Partner",
  description:
    "A global creative agency that challenges the status quo to create transformative experiences that win hearts and move markets in the eco-digital era.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en" className={inter.variable}>
      <body className="antialiased">{children}</body>
    </html>
  );
}

"use client";

import { useState, useRef, useEffect } from "react";

const navLinks = [
  { label: "Insights", href: "#insights" },
  { label: "Work", href: "#work" },
  { label: "Services", href: "#services" },
  { label: "Culture", href: "#team" },
  { label: "Make Your Mark", href: "#cta-banner" },
  { label: "Contact Us", href: "#footer" },
];

const languages = [
  { code: "EN", label: "Global EN" },
  { code: "FR", label: "France FR" },
  { code: "CN", label: "China CN" },
];

export default function Navigation() {
  const [langOpen, setLangOpen] = useState(false);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [activeLang, setActiveLang] = useState(languages[0]);
  const langRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 40);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (langRef.current && !langRef.current.contains(e.target as Node)) {
        setLangOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  return (
    <header
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled
          ? "bg-bg-primary/90 backdrop-blur-md border-b border-border"
          : "bg-transparent"
      }`}
    >
      <div className="max-w-[1440px] mx-auto px-6 lg:px-12">
        <nav className="flex items-center justify-between h-16 lg:h-20">
          {/* Logo */}
          <a href="#" className="flex items-center gap-2">
            <span className="text-xl lg:text-2xl font-bold tracking-tight text-white">
              Leap Studio
            </span>
          </a>

          {/* Desktop Nav */}
          <div className="hidden lg:flex items-center gap-8">
            {navLinks.map((link) => (
              <a
                key={link.label}
                href={link.href}
                className="text-sm text-text-secondary hover:text-white transition-colors duration-200"
              >
                {link.label}
              </a>
            ))}
          </div>

          {/* Right side */}
          <div className="flex items-center gap-4">
            {/* Language Selector */}
            <div className="relative" ref={langRef}>
              <button
                onClick={() => setLangOpen(!langOpen)}
                className="flex items-center gap-1.5 text-sm text-text-secondary hover:text-white transition-colors"
              >
                <i className="ri-global-line text-base"></i>
                <span className="hidden sm:inline">{activeLang.label}</span>
                <i
                  className={`ri-arrow-down-s-line transition-transform ${
                    langOpen ? "rotate-180" : ""
                  }`}
                ></i>
              </button>
              {langOpen && (
                <div className="absolute right-0 top-full mt-2 w-44 bg-bg-elevated border border-border rounded-lg shadow-xl overflow-hidden">
                  {languages.map((lang) => (
                    <button
                      key={lang.code}
                      onClick={() => {
                        setActiveLang(lang);
                        setLangOpen(false);
                      }}
                      className={`w-full text-left px-4 py-2.5 text-sm transition-colors ${
                        activeLang.code === lang.code
                          ? "text-white bg-white/5"
                          : "text-text-secondary hover:text-white hover:bg-white/5"
                      }`}
                    >
                      {lang.label}
                    </button>
                  ))}
                </div>
              )}
            </div>

            {/* Mobile menu toggle */}
            <button
              onClick={() => setMobileOpen(!mobileOpen)}
              className="lg:hidden text-white text-2xl"
            >
              <i className={mobileOpen ? "ri-close-line" : "ri-menu-line"}></i>
            </button>
          </div>
        </nav>
      </div>

      {/* Mobile Nav */}
      {mobileOpen && (
        <div className="lg:hidden bg-bg-primary/95 backdrop-blur-md border-t border-border">
          <div className="px-6 py-4 flex flex-col gap-1">
            {navLinks.map((link) => (
              <a
                key={link.label}
                href={link.href}
                onClick={() => setMobileOpen(false)}
                className="py-3 text-text-secondary hover:text-white transition-colors"
              >
                {link.label}
              </a>
            ))}
          </div>
        </div>
      )}
    </header>
  );
}

"use client";

import { useState, useEffect } from "react";

export default function CookieConsent() {
  const [visible, setVisible] = useState(false);
  const [settingsOpen, setSettingsOpen] = useState(false);

  useEffect(() => {
    const accepted = localStorage.getItem("cookies-accepted");
    if (!accepted) {
      setVisible(true);
    }
  }, []);

  const acceptAll = () => {
    localStorage.setItem("cookies-accepted", "all");
    setVisible(false);
    setSettingsOpen(false);
  };

  const declineAll = () => {
    localStorage.setItem("cookies-accepted", "none");
    setVisible(false);
    setSettingsOpen(false);
  };

  if (!visible) return null;

  return (
    <>
      {/* Banner */}
      <div className="fixed bottom-0 left-0 right-0 z-50 bg-bg-elevated border-t border-border">
        <div className="max-w-[1440px] mx-auto px-6 lg:px-12 py-4 lg:py-5">
          <div className="flex flex-col lg:flex-row items-start lg:items-center justify-between gap-4">
            <p className="text-sm text-text-secondary max-w-2xl">
              We use cookies to enhance your browsing experience, serve personalized content, and analyze our traffic. By clicking &quot;Accept All&quot;, you consent to our use of cookies.
            </p>
            <div className="flex items-center gap-3 shrink-0">
              <button
                onClick={() => setSettingsOpen(true)}
                className="text-sm text-text-secondary hover:text-white transition-colors px-4 py-2"
              >
                Cookie Settings
              </button>
              <button
                onClick={declineAll}
                className="text-sm text-text-secondary hover:text-white transition-colors px-4 py-2 border border-border rounded-md"
              >
                Decline All
              </button>
              <button
                onClick={acceptAll}
                className="text-sm font-medium text-white bg-accent hover:bg-accent-hover transition-colors px-5 py-2 rounded-md"
              >
                Accept All
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Settings Modal */}
      {settingsOpen && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-bg-elevated border border-border rounded-xl max-w-md w-full p-6">
            <div className="flex items-center justify-between mb-4">
              <h3 className="text-lg font-semibold text-white">Cookie Settings</h3>
              <button
                onClick={() => setSettingsOpen(false)}
                className="text-text-muted hover:text-white transition-colors"
              >
                <i className="ri-close-line text-xl"></i>
              </button>
            </div>
            <p className="text-sm text-text-secondary mb-6">
              Manage your cookie preferences. Essential cookies are always enabled to ensure the site functions correctly.
            </p>
            <div className="space-y-4 mb-6">
              <div className="flex items-center justify-between py-3 border-b border-border">
                <div>
                  <p className="text-sm font-medium text-white">Essential</p>
                  <p className="text-xs text-text-muted">Required for the site to work</p>
                </div>
                <span className="text-xs text-text-muted bg-bg-secondary px-2 py-1 rounded">Always on</span>
              </div>
              <div className="flex items-center justify-between py-3 border-b border-border">
                <div>
                  <p className="text-sm font-medium text-white">Analytics</p>
                  <p className="text-xs text-text-muted">Helps us improve our website</p>
                </div>
                <label className="relative inline-flex items-center cursor-pointer">
                  <input type="checkbox" className="sr-only peer" defaultChecked />
                  <div className="w-9 h-5 bg-bg-secondary peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-accent"></div>
                </label>
              </div>
              <div className="flex items-center justify-between py-3">
                <div>
                  <p className="text-sm font-medium text-white">Marketing</p>
                  <p className="text-xs text-text-muted">Used to deliver relevant ads</p>
                </div>
                <label className="relative inline-flex items-center cursor-pointer">
                  <input type="checkbox" className="sr-only peer" />
                  <div className="w-9 h-5 bg-bg-secondary peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-4 after:w-4 after:transition-all peer-checked:bg-accent"></div>
                </label>
              </div>
            </div>
            <div className="flex items-center gap-3">
              <button
                onClick={declineAll}
                className="flex-1 text-sm text-text-secondary hover:text-white transition-colors px-4 py-2.5 border border-border rounded-md"
              >
                Decline All
              </button>
              <button
                onClick={acceptAll}
                className="flex-1 text-sm font-medium text-white bg-accent hover:bg-accent-hover transition-colors px-4 py-2.5 rounded-md"
              >
                Accept All
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

