export default function HeroSection() {
  const [current, setCurrent] = useState(0);
  const [isTransitioning, setIsTransitioning] = useState(false);

  const goTo = useCallback(
    (index: number) => {
      if (isTransitioning || index === current) return;
      setIsTransitioning(true);
      setCurrent(index);
      setTimeout(() => setIsTransitioning(false), 600);
    },
    [current, isTransitioning]
  );

  const next = useCallback(() => {
    goTo((current + 1) % slides.length);
  }, [current, goTo]);

  const prev = useCallback(() => {
    goTo((current - 1 + slides.length) % slides.length);
  }, [current, goTo]);

  useEffect(() => {
    const timer = setInterval(next, 6000);
    return () => clearInterval(timer);
  }, [next]);

  return (
    <section className="relative min-h-screen flex items-end overflow-hidden">
      {/* Background Images */}
      {slides.map((slide, index) => (
        <div
          key={slide.id}
          className={`absolute inset-0 transition-opacity duration-700 ease-in-out ${
            index === current ? "opacity-100" : "opacity-0"
          }`}
        >
          <div
            className="absolute inset-0 bg-cover bg-center"
            style={{ backgroundImage: `url(${slide.image})` }}
          />
          <div className="absolute inset-0 bg-gradient-to-t from-bg-primary via-bg-primary/70 to-bg-primary/30" />
        </div>
      ))}

      {/* Content */}
      <div className="relative z-10 w-full max-w-[1440px] mx-auto px-6 lg:px-12 pb-16 lg:pb-24 pt-32">
        <div className="max-w-3xl">
          {slides.map((slide, index) => (
            <div
              key={slide.id}
              className={`transition-all duration-600 ${
                index === current
                  ? "opacity-100 translate-y-0"
                  : "opacity-0 translate-y-6 absolute pointer-events-none"
              }`}
            >
              <span className="inline-block text-xs font-semibold tracking-widest uppercase text-accent mb-4">
                {slide.eyebrow}
              </span>
              <h1 className="text-4xl sm:text-5xl lg:text-7xl font-bold text-white leading-[1.1] tracking-tight mb-6">
                {slide.title}
              </h1>
              <p className="text-base lg:text-lg text-text-secondary leading-relaxed mb-8 max-w-xl">
                {slide.description}
              </p>
              <a
                href="#"
                className="inline-flex items-center gap-2 text-sm font-medium text-white bg-accent hover:bg-accent-hover transition-colors px-6 py-3 rounded-md"
              >
                {slide.cta}
                <i className="ri-arrow-right-line"></i>
              </a>
            </div>
          ))}
        </div>

        {/* Controls */}
        <div className="flex items-center justify-between mt-12 lg:mt-16">
          {/* Arrows */}
          <div className="flex items-center gap-3">
            <button
              onClick={prev}
              className="w-10 h-10 lg:w-12 lg:h-12 flex items-center justify-center rounded-full border border-border text-white hover:bg-white/10 transition-colors"
              aria-label="Previous slide"
            >
              <i className="ri-arrow-left-line text-lg"></i>
            </button>
            <button
              onClick={next}
              className="w-10 h-10 lg:w-12 lg:h-12 flex items-center justify-center rounded-full border border-border text-white hover:bg-white/10 transition-colors"
              aria-label="Next slide"
            >
              <i className="ri-arrow-right-line text-lg"></i>
            </button>
          </div>

          {/* Dots + Counter */}
          <div className="flex items-center gap-4">
            <div className="hidden sm:flex items-center gap-2">
              {slides.map((_, index) => (
                <button
                  key={index}
                  onClick={() => goTo(index)}
                  className={`h-1.5 rounded-full transition-all duration-300 ${
                    index === current
                      ? "w-8 bg-white"
                      : "w-1.5 bg-white/30 hover:bg-white/50"
                  }`}
                  aria-label={`Go to slide ${index + 1}`}
                />
              ))}
            </div>
            <span className="text-sm text-text-muted font-medium tabular-nums">
              {String(current + 1).padStart(2, "0")} / {String(slides.length).padStart(2, "0")}
            </span>
          </div>
        </div>
      </div>
    </section>
  );
}

